import json, sys

def solve(req):
    initial = req['initial']
    final = req['final']
    txs = req['transactions']
    n = len(txs)
    if n == 0:
        return {"order": [] if initial == final else None}

    # ---- collect keys that can ever be present or are referenced ----
    keys = set(initial.keys()) | set(final.keys())
    for tx in txs:
        for op in tx['ops']:
            typ = op[0]
            if typ in ('get', 'put', 'del', 'cas'):
                keys.add(op[1])
    keys = sorted(keys)
    K = len(keys)
    key_idx = {k: i for i, k in enumerate(keys)}

    # ---- domains of producible values per key ----
    domains = []
    for k in keys:
        vals = set()
        if k in initial:
            vals.add(initial[k])
        for tx in txs:
            for op in tx['ops']:
                if op[0] == 'put' and op[1] == k:
                    vals.add(op[2])
                elif op[0] == 'cas' and op[1] == k and op[3] is not None:
                    vals.add(op[3])
        domains.append([None] + sorted(vals))
    dom_index = [{v: i for i, v in enumerate(dom)} for dom in domains]

    # ---- early impossibility checks ----
    for tx in txs:
        for op in tx['ops']:
            typ = op[0]
            if typ == 'get':
                exp = op[2]
                if exp is not None and exp not in dom_index[key_idx[op[1]]]:
                    return {"order": None}
            elif typ == 'cas':
                old, new, want = op[2], op[3], op[4]
                if want is True and old is not None and old not in dom_index[key_idx[op[1]]]:
                    return {"order": None}
            elif typ == 'scan':
                for pair in op[3]:
                    k, v = pair
                    if k not in key_idx:
                        return {"order": None}
                    if v is not None and v not in dom_index[key_idx[k]]:
                        return {"order": None}
    for k, v in final.items():
        if v is not None and v not in dom_index[key_idx[k]]:
            return {"order": None}

    # ---- mixed-radix state encoding ----
    strides = []
    prod = 1
    for dom in domains:
        strides.append(prod)
        prod *= len(dom)

    def digits_to_state(digs):
        s = 0
        for i, d in enumerate(digs):
            s += d * strides[i]
        return s

    init_digits = [dom_index[i][initial.get(k)] for i, k in enumerate(keys)]
    fin_digits = [dom_index[i][final.get(k)] for i, k in enumerate(keys)]
    init_state = digits_to_state(init_digits)
    fin_state = digits_to_state(fin_digits)

    # ---- precompute operations with key indices ----
    tx_ops = []
    for tx in txs:
        ops = []
        for op in tx['ops']:
            typ = op[0]
            if typ == 'get':
                ops.append(('get', key_idx[op[1]], op[2]))
            elif typ == 'put':
                ops.append(('put', key_idx[op[1]], op[2]))
            elif typ == 'del':
                ops.append(('del', key_idx[op[1]]))
            elif typ == 'cas':
                ops.append(('cas', key_idx[op[1]], op[2], op[3], op[4]))
            elif typ == 'scan':
                low, high = op[1], op[2]
                rng = [i for i, k in enumerate(keys) if low <= k < high]
                ops.append(('scan', rng, op[3]))
        tx_ops.append(ops)

    # ---- transition memoization ----
    trans_memo = [dict() for _ in range(n)]

    def simulate(ti, state):
        digs = [(state // strides[i]) % len(domains[i]) for i in range(K)]
        for op in tx_ops[ti]:
            typ = op[0]
            if typ == 'get':
                _, ki, exp = op
                if domains[ki][digs[ki]] != exp:
                    return -1
            elif typ == 'put':
                _, ki, val = op
                digs[ki] = dom_index[ki][val]
            elif typ == 'del':
                _, ki = op
                digs[ki] = 0
            elif typ == 'cas':
                _, ki, old, new, want = op
                v = domains[ki][digs[ki]]
                ok = (v == old)
                if ok != want:
                    return -1
                if ok:
                    if new is None:
                        digs[ki] = 0
                    else:
                        digs[ki] = dom_index[ki][new]
            elif typ == 'scan':
                _, rng, expected = op
                actual = []
                for ki in rng:
                    v = domains[ki][digs[ki]]
                    if v is not None:
                        actual.append([keys[ki], v])
                if actual != expected:
                    return -1
        s = 0
        for i, d in enumerate(digs):
            s += d * strides[i]
        return s

    def get_trans(ti, state):
        memo = trans_memo[ti]
        res = memo.get(state)
        if res is None:
            res = simulate(ti, state)
            memo[state] = res
        return res

    # ---- precedence constraints ----
    preds = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j and txs[j]['end'] <= txs[i]['start']:
                preds[i] |= (1 << j)
    full = (1 << n) - 1

    # ---- writes / producers for pruning ----
    tx_writes = []
    for ti in range(n):
        w = {}
        for op in tx_ops[ti]:
            if op[0] == 'put':
                _, ki, val = op
                w.setdefault(ki, set()).add(dom_index[ki][val])
            elif op[0] == 'cas':
                _, ki, old, new, want = op
                if new is None:
                    w.setdefault(ki, set()).add(0)
                else:
                    w.setdefault(ki, set()).add(dom_index[ki][new])
        tx_writes.append(w)
    key_producers = [[0] * len(domains[ki]) for ki in range(K)]
    for ti in range(n):
        for ki, vals in tx_writes[ti].items():
            for d in vals:
                key_producers[ki][d] |= (1 << ti)

    failed = set()
    path = [None] * n

    # simple heuristic: try transactions that write keys currently wrong first?
    # We'll sort available by a score computed dynamically.

    def dfs(mask, state, depth):
        if mask == full:
            return state == fin_state
        key = (mask, state)
        if key in failed:
            return False

        # ---- pruning: final reachability ----
        remaining = full ^ mask
        digs = [(state // strides[i]) % len(domains[i]) for i in range(K)]
        for ki in range(K):
            cur = digs[ki]
            fin = fin_digits[ki]
            if cur != fin:
                # need some remaining transaction able to write fin
                if (key_producers[ki][fin] & remaining) == 0:
                    failed.add(key)
                    return False

        # ---- available transactions ----
        avail = []
        for i in range(n):
            if (mask >> i) & 1:
                continue
            if (preds[i] & mask) == preds[i]:
                avail.append(i)
        if not avail:
            failed.add(key)
            return False

        # Heuristic: prefer transactions that are "forced" or that fix wrong keys.
        # Compute a score: number of keys currently differing from final that the tx writes.
        def score(i):
            s = 0
            for ki in tx_writes[i]:
                if digs[ki] != fin_digits[ki]:
                    s += 1
            return -s  # smaller (more negative) = more useful
        avail.sort(key=score)

        for i in avail:
            ns = get_trans(i, state)
            if ns != -1:
                path[depth] = txs[i]['id']
                if dfs(mask | (1 << i), ns, depth + 1):
                    return True
        failed.add(key)
        return False

    if dfs(0, init_state, 0):
        return {"order": path}
    return {"order": None}

def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        res = solve(req)
        out.write(json.dumps(res) + "\n")
        out.flush()

if __name__ == '__main__':
    main()
