                k = rng.choice(keys)
                ops.append(['del', k])
            elif typ == 'cas':
                k = rng.choice(keys)
                old = rng.choice([None] + list(range(-9,10)))
                new = rng.choice([None] + list(range(-9,10)))
                ops.append(['cas', k, old, new, None])
            else:
