                lo = rng.choice(keys)
                hi = rng.choice(keys)
                if lo >= hi:
                    lo, hi = sorted([lo, hi])
                    if lo == hi:
                        hi = chr(ord(lo)+1) if ord(lo) < ord('z') else lo
                ops.append(['scan', lo, hi, None])
        tx_ops.append(ops)
    # choose a random valid order
    order = list(range(n))
    rng.shuffle(order)
    # simulate and fill observations
    state = dict(initial)
    for idx in order:
        for op in tx_ops[idx]:
            typ = op[0]
            if typ == 'get':
                op[2] = state.get(op[1])
            elif typ == 'put':
                state[op[1]] = op[2]
            elif typ == 'del':
                state.pop(op[1], None)
            elif typ == 'cas':
                old = op[2]
                ok = (state.get(op[1]) == old)
                op[4] = ok
                if ok:
                    if op[3] is None:
                        state.pop(op[1], None)
                    else:
                        state[op[1]] = op[3]
            else:
                lo, hi = op[1], op[2]
                pairs = sorted([[k,v] for k,v in state.items() if lo <= k < hi])
                op[3] = pairs
    final = dict(state)
