    req = copy.deepcopy(req)
    # find all observation ops
    obs = []
    for ti, tx in enumerate(req['transactions']):
        for oi, op in enumerate(tx['ops']):
            if op[0] == 'get':
                obs.append((ti, oi, 'get'))
            elif op[0] == 'cas':
                obs.append((ti, oi, 'cas'))
            elif op[0] == 'scan':
                obs.append((ti, oi, 'scan'))
    if not obs:
        return req
    ti, oi, typ = rng.choice(obs)
    op = req['transactions'][ti]['ops'][oi]
