from public_contract import valid_history

def gen_random(seed):
    rng = random.Random(seed)
    n = rng.randint(0,5)
    K = rng.randint(1,4)
    keys = [chr(ord('a')+i) for i in range(K)]
    initial = {}
    for k in keys:
        if rng.random() < 0.5:
            initial[k] = rng.randint(-2,2)
    txs = []
    for i in range(n):
        ops = []
        for _ in range(rng.randint(1,4)):
            typ = rng.choice(['get','put','del','cas','scan'])
            if typ == 'get':
                k = rng.choice(keys)
                exp = rng.choice([None] + list(range(-2,3)))
                ops.append(['get',k,exp])
            elif typ == 'put':
                k = rng.choice(keys)
                ops.append(['put',k,rng.randint(-2,2)])
            elif typ == 'del':
                k = rng.choice(keys)
                ops.append(['del',k])
            elif typ == 'cas':
                k = rng.choice(keys)
                old = rng.choice([None] + list(range(-2,3)))
                new = rng.choice([None] + list(range(-2,3)))
                want = rng.choice([True,False])
                ops.append(['cas',k,old,new,want])
            else:
                lo = rng.choice(keys)
                hi = rng.choice(keys)
                if lo >= hi:
                    lo, hi = sorted([lo,hi])
                    if lo == hi:
                        hi = chr(ord(lo)+1) if ord(lo)<ord('z') else lo
                pairs = []
                # random expected pairs
                for k in keys:
                    if lo <= k < hi and rng.random()<0.5:
                        pairs.append([k, rng.choice([None]+list(range(-2,3)))])
                pairs.sort(key=lambda x:x[0])
                ops.append(['scan',lo,hi,pairs])
        start = rng.randint(0,5)
        end = start + rng.randint(1,3)
        txs.append({'id':f't{i}','start':start,'end':end,'ops':ops})
    final = {}
    for k in keys:
        if rng.random()<0.5:
            final[k] = rng.randint(-2,2)
    return {'initial':initial,'final':final,'transactions':txs}

def brute(req):
    txs = req['transactions']
    ids = [t['id'] for t in txs]
    n = len(ids)
    for perm in itertools.permutations(ids):
        ranks = {x:i for i,x in enumerate(perm)}
        ok = True
        for a in txs:
            for b in txs:
                if a['end'] <= b['start'] and ranks[a['id']] >= ranks[b['id']]:
                    ok=False; break
            if not ok: break
        if not ok: continue
        if valid_history(req, list(perm)):
            return list(perm)
    return None

if __name__ == '__main__':
    for seed in range(5000):
        req = gen_random(seed)
        got = main.solve(req)
        bf = brute(req)
        if bf is None:
            if got['order'] is not None:
                print('FAIL seed',seed,'expected null got',got)
                print(json.dumps(req))
                sys.exit(1)
        else:
            if got['order'] is None:
                print('FAIL seed',seed,'expected order got null')
                print(json.dumps(req))
                sys.exit(1)
            if not valid_history(req, got['order']):
                print('FAIL seed',seed,'invalid order',got)
                print(json.dumps(req))
                sys.exit(1)
        if seed % 1000 == 0:
            print('seed',seed,'ok')
            sys.stdout.flush()
    print('all correct')
